-- =====================================================================
-- Formularios que Inoo tenía en Monday, ahora nativos del portal (26 oct 2026)
--  · Cinco briefs que responde el cliente como requerimientos: web y branding (reemplazan a las preguntas de
--    relleno), naming, performance y marketing (nuevos). Mismas preguntas, opciones y caminos que en Monday:
--    `mostrarSi` muestra una pregunta solo según la respuesta de otra. Copia de src/dominio/briefs.ts
--    (tests/api/db.test.ts comprueba que coinciden).
--  · Se piden solos al contratar: marketing con Social Media Pro, performance con Paid Media y naming con
--    Brandformance · marca nueva.
--  · El ingreso de cliente (lo llena Comercial en el alta) se guarda en cliente.ingreso.
-- Los requerimientos ya emitidos guardan su copia del formulario y no cambian.
-- =====================================================================

INSERT INTO plantilla_requerimiento (codigo, nombre, descripcion, servicios, dias_habiles, campos) VALUES
  ('BRIEF_WEB', 'Brief de diseño y desarrollo web', 'Lo que necesitamos saber para diseñar tu sitio.', ARRAY['WEB']::text[], 5,
   '[{"clave":"marca","etiqueta":"Nombre de la marca","tipo":"TEXTO","obligatorio":true,"seccion":"Tu marca"},{"clave":"historia","etiqueta":"Cuéntanos la historia de tu marca","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Cómo nació? ¿Qué problema resuelven?"},{"clave":"manualMarca","etiqueta":"¿Cuentas con un manual de marca?","tipo":"OPCION","obligatorio":false,"opciones":["Sí","No","Solo tengo logo"]},{"clave":"archivosMarca","etiqueta":"Sube tu manual de marca o tu logo","tipo":"ARCHIVOS","obligatorio":false,"ayuda":"Illustrator o PDF.","mostrarSi":{"campo":"manualMarca","valores":["Sí","Solo tengo logo"]}},{"clave":"situacion","etiqueta":"Situación actual de tu página web","tipo":"OPCION","obligatorio":true,"seccion":"Tu proyecto","opciones":["Diseño web nuevo a partir de una página web existente","Diseño web desde cero"]},{"clave":"tipoProyecto","etiqueta":"¿Qué tipo de sitio web necesitas?","tipo":"OPCION","obligatorio":true,"opciones":["Landing page","Web corporativa","Sistema intranet / extranet","Web e-commerce","Web catálogo","One page"],"mostrarSi":{"campo":"situacion","valores":["Diseño web desde cero"]}},{"clave":"blog","etiqueta":"¿Necesitas un blog para publicar noticias o artículos?","tipo":"OPCION","obligatorio":false,"opciones":["Sí","No"],"ayuda":"Sirve para mantener tu web al día, compartir novedades y atraer visitas con contenido de valor.","mostrarSi":{"campo":"tipoProyecto","valores":["Web corporativa"]}},{"clave":"cantidadProductos","etiqueta":"Cantidad de productos","tipo":"OPCION","obligatorio":false,"opciones":["1 a 25","25 a 100","Más de 100"],"mostrarSi":{"campo":"tipoProyecto","valores":["Web e-commerce","Web catálogo"]}},{"clave":"metodosPago","etiqueta":"¿Qué métodos de pago usarás?","tipo":"TEXTO","obligatorio":false,"ayuda":"Mercado Pago, Culqi, Izipay, transferencia…","mostrarSi":{"campo":"tipoProyecto","valores":["Web e-commerce"]}},{"clave":"productoPromocionar","etiqueta":"¿Cuál es el producto o servicio específico a promocionar?","tipo":"TEXTO_LARGO","obligatorio":false,"mostrarSi":{"campo":"tipoProyecto","valores":["Landing page","One page"]}},{"clave":"objetivos","etiqueta":"Objetivo principal del nuevo sitio","tipo":"OPCION","obligatorio":true,"opciones":["Actualización de contenido","Implementar un enfoque en ventas","Mejorar el diseño en general","Optimización para estrategia SEO","Todas las anteriores"],"mostrarSi":{"campo":"situacion","valores":["Diseño web nuevo a partir de una página web existente"]}},{"clave":"sitioActual","etiqueta":"Sobre tu sitio web actual","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿En qué año se diseñó? ¿Qué tiene de bueno? ¿Qué tiene de malo?","mostrarSi":{"campo":"situacion","valores":["Diseño web nuevo a partir de una página web existente"]}},{"clave":"paises","etiqueta":"Top 3 de países que visitan tu sitio","tipo":"TEXTO","obligatorio":false,"mostrarSi":{"campo":"situacion","valores":["Diseño web nuevo a partir de una página web existente"]}},{"clave":"ciudades","etiqueta":"Top 5 de ciudades que visitan tu sitio","tipo":"TEXTO","obligatorio":false,"mostrarSi":{"campo":"situacion","valores":["Diseño web nuevo a partir de una página web existente"]}},{"clave":"contacto","etiqueta":"Datos de contacto y ubicación","tipo":"TEXTO_LARGO","obligatorio":true,"ayuda":"Los datos oficiales que aparecerán en tu sitio: dirección (calle, número, urbanización y oficina o local), teléfonos, correos y direcciones de sucursales."},{"clave":"preguntasFrecuentes","etiqueta":"Preguntas frecuentes al comprar tu producto o servicio","tipo":"TEXTO_LARGO","obligatorio":false,"mostrarSi":{"campo":"situacion","valores":["Diseño web nuevo a partir de una página web existente","Diseño web desde cero"]}},{"clave":"motivosNoCompra","etiqueta":"Motivos más frecuentes por los que no compran tu producto o servicio","tipo":"TEXTO_LARGO","obligatorio":false,"mostrarSi":{"campo":"situacion","valores":["Diseño web nuevo a partir de una página web existente"]}},{"clave":"competencia","etiqueta":"Menciona 3 marcas de tu competencia directa","tipo":"TEXTO","obligatorio":false,"mostrarSi":{"campo":"situacion","valores":["Diseño web desde cero"]}},{"clave":"inspiracion","etiqueta":"3 sitios web que te inspiren para el diseño","tipo":"LISTA","obligatorio":false,"ayuda":"Sean o no de tu sector. Un enlace por línea.","mostrarSi":{"campo":"situacion","valores":["Diseño web desde cero"]}},{"clave":"estilo","etiqueta":"Estilo de la nueva imagen de tu página web","tipo":"OPCION","obligatorio":false,"opciones":["Tradicional: colores tradicionales, cuadrada y muy exacta","Natural: colores claros, simple y sencilla","Elegante: colores oscuros, bien proporcionada y poco texto","Seductor: colores cálidos","Creativo: colores adicionales a la paleta, con estructuras libres y diferentes","Romántico: colores pastel, un poco más libre en estructura","Dramático: colores fuertes y llamativos, para impactar"],"mostrarSi":{"campo":"situacion","valores":["Diseño web desde cero"]}},{"clave":"fotos","etiqueta":"Fotografías para el sitio","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Tienen fotografías propias? ¿Quieren comprar fotos de stock? ¿Piensan hacer una sesión de fotos?","mostrarSi":{"campo":"situacion","valores":["Diseño web desde cero"]}},{"clave":"videos","etiqueta":"Videos para el sitio","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Tienen videos propios? ¿Quieren comprar videos de stock? ¿Piensan hacer una sesión de grabación?","mostrarSi":{"campo":"situacion","valores":["Diseño web desde cero"]}},{"clave":"contenido","etiqueta":"Contenido del sitio web","tipo":"OPCION","obligatorio":false,"opciones":["Lo realizará la agencia","Lo realizaremos internamente"],"mostrarSi":{"campo":"situacion","valores":["Diseño web desde cero"]}},{"clave":"hosting","etiqueta":"¿Cuentas con hosting y dominio?","tipo":"OPCION","obligatorio":false,"seccion":"Hosting y dominio","opciones":["Sí","No","Solo tengo hosting","Solo tengo dominio"]},{"clave":"proveedorHosting","etiqueta":"¿Dónde están tu hosting y tu dominio?","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"La dirección y el proveedor (Hostinger, GoDaddy…). No escribas contraseñas aquí: los accesos te los pedimos aparte.","mostrarSi":{"campo":"hosting","valores":["Sí","Solo tengo hosting","Solo tengo dominio"]}}]'),
  ('BRIEF_BRANDING', 'Brief de branding', 'Para conocer los alcances e intenciones de tu marca antes de diseñarla (o rediseñarla).', ARRAY['BRANDFORMANCE']::text[], 5,
   '[{"clave":"marca","etiqueta":"Nombre de la marca","tipo":"TEXTO","obligatorio":true,"seccion":"Tu empresa"},{"clave":"descripcion","etiqueta":"Descripción de la empresa","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"tiempoMercado","etiqueta":"¿Cuántos años lleva la empresa en el mercado?","tipo":"NUMERO","obligatorio":false},{"clave":"motivacion","etiqueta":"¿Qué te motivó a empezar este negocio u organización?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"mision","etiqueta":"Misión","tipo":"TEXTO","obligatorio":false},{"clave":"vision","etiqueta":"Visión","tipo":"TEXTO","obligatorio":false},{"clave":"valores","etiqueta":"Menciona los valores de tu marca","tipo":"TEXTO","obligatorio":false},{"clave":"personalidad","etiqueta":"¿Cuál consideras que es la personalidad de tu marca?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"productos","etiqueta":"Información sobre los productos o servicios que brinda la marca","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Con detalle."},{"clave":"objetivosGenerales","etiqueta":"Menciona los objetivos generales de tu marca","tipo":"TEXTO_LARGO","obligatorio":false,"seccion":"Lo que quieres lograr"},{"clave":"proposito","etiqueta":"¿Cuál es el propósito de tu marca?","tipo":"TEXTO","obligatorio":false},{"clave":"objetivoEspecifico","etiqueta":"¿Cuál es su objetivo específico?","tipo":"TEXTO","obligatorio":false},{"clave":"competenciaDirecta","etiqueta":"¿Qué marcas consideras tu competencia directa?","tipo":"TEXTO_LARGO","obligatorio":false,"seccion":"Competencia y público","ayuda":"Marcas que ofrecen el mismo servicio o producto que tu marca."},{"clave":"competenciaIndirecta","etiqueta":"¿Qué marcas consideras tu competencia indirecta?","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Marcas que ofrecen servicios o productos similares o sustitutos al tuyo."},{"clave":"diferencial","etiqueta":"¿Por qué un cliente debería elegir tu empresa frente a la competencia?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"demograficos","etiqueta":"Datos demográficos de tu público","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Género, dónde viven, sus estudios, nivel socioeconómico."},{"clave":"psicograficos","etiqueta":"Datos psicográficos de tu público","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Actitudes, personalidad, hábitos de consumo, estilo de vida (trabajo, entretenimiento)."},{"clave":"publicoPrincipal","etiqueta":"¿Quién es el público objetivo principal?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"publicidad","etiqueta":"¿Cuáles son tus principales formas de hacer publicidad?","tipo":"TEXTO","obligatorio":false},{"clave":"comoTeConocen","etiqueta":"¿Cómo se entera la mayoría de tus clientes de tu empresa, servicio o producto?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"think","etiqueta":"Think: ¿qué quieres que piense tu usuario?","tipo":"TEXTO_LARGO","obligatorio":false,"seccion":"Concepto e identidad visual"},{"clave":"feel","etiqueta":"Feel: ¿qué quieres que sienta tu usuario?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"do","etiqueta":"Do: ¿qué quieres que haga tu usuario?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"concepto","etiqueta":"¿Cuál consideras que es el concepto de tu marca?","tipo":"TEXTO","obligatorio":false},{"clave":"colores","etiqueta":"¿Qué paletas o gamas de colores prefieres? ¿Alguna razón en particular?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"elementosLogo","etiqueta":"¿Hay algún elemento que quisieras incluir en el logo?","tipo":"TEXTO","obligatorio":false},{"clave":"preferencias","etiqueta":"¿Qué prefieres en íconos, tipografía, colores, etc.?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"referencias","etiqueta":"Referencias","tipo":"ARCHIVOS","obligatorio":false},{"clave":"papeleria","etiqueta":"Papelería y merchandising que deseas incluir","tipo":"OPCIONES","obligatorio":false,"ayuda":"Marca según el paquete contratado.","opciones":["Carpeta / folder","Cobertura de camión","Hoja membretada","Lanyard","Lapicero","Sobres","Tarjeta de presentación","Uniforme (polo)","Otros"]},{"clave":"papeleriaOtros","etiqueta":"Si marcaste «Otros», especifica cuáles","tipo":"TEXTO","obligatorio":false,"mostrarSi":{"campo":"papeleria","valores":["Otros"]}},{"clave":"comentarios","etiqueta":"Comentarios","tipo":"TEXTO_LARGO","obligatorio":false}]'),
  ('BRIEF_NAMING', 'Brief de naming', 'Para encontrar el nombre de tu marca.', ARRAY['BRANDFORMANCE']::text[], 5,
   '[{"clave":"empresa","etiqueta":"Nombre del cliente o empresa","tipo":"TEXTO","obligatorio":true},{"clave":"contexto","etiqueta":"¿Existe algún contexto previo a la creación de la marca?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"rubro","etiqueta":"¿Qué producto o rubro ofrece la marca?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"publico","etiqueta":"¿Te diriges a un público en específico?","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Sexo, edad y nivel socioeconómico."},{"clave":"diferencial","etiqueta":"¿Qué te diferencia de tu competencia?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"valor","etiqueta":"¿Cuál es el valor de marca que quieres proyectar en tu naming?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"comoHabla","etiqueta":"¿Cómo te gustaría que hable tu marca?","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Amigable, formal, sarcástica, etc."},{"clave":"evocar","etiqueta":"¿Quieres evocar algo personal (nombre, apellidos, etc.) o basarte en algún concepto?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"referenciaProducto","etiqueta":"¿Quieres hacer referencia a algún producto en específico o a los productos que vendes?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"idioma","etiqueta":"¿Alguna preferencia de idioma para el naming?","tipo":"TEXTO","obligatorio":false,"ayuda":"Español, inglés, etc."},{"clave":"recordacion","etiqueta":"¿Debe ser fácil de recordar? ¿Prefieres un naming corto, siglas o un nombre completo?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"cincoPalabras","etiqueta":"Menciona las primeras 5 palabras que se te vienen a la cabeza al pensar en tu marca","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"palabrasEvitar","etiqueta":"¿Hay alguna palabra que no quieras que se relacione con tu marca?","tipo":"TEXTO_LARGO","obligatorio":false}]'),
  ('BRIEF_PERFORMANCE', 'Brief de performance', 'Tu empresa, tus metas y lo que ya probaste en publicidad digital.', ARRAY['PAID_MEDIA']::text[], 5,
   '[{"clave":"empresa","etiqueta":"Nombre de la empresa","tipo":"TEXTO","obligatorio":true,"seccion":"Descripción de la empresa"},{"clave":"sector","etiqueta":"Sector o industria","tipo":"TEXTO","obligatorio":true},{"clave":"tamano","etiqueta":"Tamaño de la empresa","tipo":"TEXTO","obligatorio":true,"ayuda":"Número de colaboradores y facturación mensual."},{"clave":"descripcion","etiqueta":"Pequeña descripción de la empresa","tipo":"TEXTO","obligatorio":true},{"clave":"misionVision","etiqueta":"¿Cuál es la misión y visión de tu empresa?","tipo":"TEXTO_LARGO","obligatorio":true},{"clave":"tiempoMercado","etiqueta":"¿Cuánto tiempo lleva la empresa en el mercado?","tipo":"TEXTO","obligatorio":false},{"clave":"productos","etiqueta":"¿Cuáles son los productos o servicios principales que ofrece tu empresa?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"responsables","etiqueta":"¿Quiénes son los responsables?","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Nombres, teléfono y correo."},{"clave":"objetivos","etiqueta":"¿Cuáles son los principales objetivos de tu empresa a corto y largo plazo?","tipo":"TEXTO_LARGO","obligatorio":false,"seccion":"Objetivos empresariales"},{"clave":"metasInoo","etiqueta":"¿Qué metas quieres alcanzar con el servicio de Inoo?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"competencia","etiqueta":"¿Qué empresas o marcas consideras tu competencia directa?","tipo":"TEXTO_LARGO","obligatorio":false,"seccion":"Competencia","ayuda":"De 5 a 10 competidores."},{"clave":"presupuesto","etiqueta":"¿Cuál es tu presupuesto actual de marketing digital?","tipo":"TEXTO_LARGO","obligatorio":false,"seccion":"Estrategias de marketing anteriores"},{"clave":"redes","etiqueta":"¿En qué redes sociales tienen presencia?","tipo":"TEXTO","obligatorio":false},{"clave":"frecuencia","etiqueta":"En los últimos meses, ¿con qué frecuencia publicaron en sus redes sociales?","tipo":"TEXTO","obligatorio":false,"ayuda":"Total de publicaciones por mes o por semana."},{"clave":"campanasPrevias","etiqueta":"¿Han hecho campañas de anuncios pagados en redes? ¿En qué plataformas y con qué presupuesto?","tipo":"TEXTO","obligatorio":false},{"clave":"resultados","etiqueta":"¿Qué resultados obtuvieron con esas estrategias?","tipo":"TEXTO_LARGO","obligatorio":false}]'),
  ('BRIEF_MARKETING', 'Brief de marketing', 'Tu marca, tu público y tu identidad visual, para arrancar con tus redes.', ARRAY['SOCIAL_MEDIA_PRO']::text[], 5,
   '[{"clave":"marca","etiqueta":"Nombre de la marca","tipo":"TEXTO","obligatorio":false,"seccion":"Tu marca"},{"clave":"origen","etiqueta":"¿Cómo nació la empresa?","tipo":"TEXTO","obligatorio":false},{"clave":"tiempoMercado","etiqueta":"¿Cuántos años lleva la empresa en el mercado?","tipo":"NUMERO","obligatorio":false},{"clave":"producto","etiqueta":"Descripción del producto o servicio","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"precio","etiqueta":"¿Cómo consideras tu precio?","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"En relación al mercado."},{"clave":"publicidad","etiqueta":"¿Cuáles son tus principales formas de hacer publicidad? ¿Cuál será el presupuesto para pauta?","tipo":"TEXTO","obligatorio":false},{"clave":"agenciaPrevia","etiqueta":"¿Has trabajado antes con alguna agencia de marketing?","tipo":"TEXTO","obligatorio":false},{"clave":"beneficiosBasicos","etiqueta":"Beneficios básicos o comunes de la categoría","tipo":"TEXTO_LARGO","obligatorio":false,"seccion":"Beneficios y competencia","ayuda":"Incluye el porqué de cada beneficio."},{"clave":"beneficioDiferencial","etiqueta":"Beneficio principal o diferencial","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Qué beneficio tiene tu producto o servicio que lo diferencia del resto, y por qué?"},{"clave":"competenciaDirecta","etiqueta":"¿Qué marcas consideras tu competencia directa?","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Marcas que ofrecen el mismo servicio o producto que tu marca."},{"clave":"competenciaIndirecta","etiqueta":"¿Qué marcas consideras tu competencia indirecta?","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Marcas que ofrecen servicios o productos similares o sustitutos al tuyo."},{"clave":"demograficos","etiqueta":"Datos demográficos de tu público","tipo":"TEXTO_LARGO","obligatorio":false,"seccion":"Tu público","ayuda":"Género, dónde viven, sus estudios, nivel socioeconómico."},{"clave":"psicograficos","etiqueta":"Datos psicográficos de tu público","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Actitudes, personalidad, hábitos de consumo, estilo de vida (trabajo, entretenimiento)."},{"clave":"objetivo","etiqueta":"Objetivo de marketing","tipo":"TEXTO_LARGO","obligatorio":false,"seccion":"Estrategia","ayuda":"¿Qué objetivos quieres lograr?"},{"clave":"posicionamiento","etiqueta":"Posicionamiento","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Cómo queremos ser percibidos en la mente de los consumidores?"},{"clave":"promesa","etiqueta":"Promesa básica","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Qué le vas a ofrecer a tu consumidor?"},{"clave":"tono","etiqueta":"Tono de comunicación","tipo":"TEXTO","obligatorio":false,"ayuda":"Moderno, tecnológico, formal, informal, elegante, racional, emotivo, agresivo, etc."},{"clave":"redes","etiqueta":"Redes sociales","tipo":"TEXTO","obligatorio":false,"ayuda":"¿Qué redes usas (Facebook, Instagram, TikTok, LinkedIn)? ¿Tienes página web?"},{"clave":"locacion","etiqueta":"Locación del local","tipo":"TEXTO","obligatorio":false,"ayuda":"¿En qué lugar se harían las sesiones?"},{"clave":"manualMarca","etiqueta":"¿Cuentas con manual de marca?","tipo":"OPCION","obligatorio":false,"seccion":"Identidad visual","opciones":["Sí","No","Solo logo"],"ayuda":"Logo, colores, tipografía, estilo visual."},{"clave":"archivosMarca","etiqueta":"Sube tu manual y/o tu logo","tipo":"ARCHIVOS","obligatorio":false,"mostrarSi":{"campo":"manualMarca","valores":["Sí","Solo logo"]}},{"clave":"personalidad","etiqueta":"Personalidad de marca","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Cómo quieres que se perciba visualmente tu marca en redes? (Moderna, elegante, juvenil, sobria, artesanal, etc.)"},{"clave":"colores","etiqueta":"Colores","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Qué colores crees que identifican mejor a tu marca? ¿Hay alguno que no te gustaría que se use?"},{"clave":"estilos","etiqueta":"Estilos","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Cómo prefieres que sean las publicaciones? (Coloridas, minimalistas, ilustradas, fotográficas, tipográficas, etc.)"},{"clave":"referentes","etiqueta":"Referentes","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Hay alguna marca o cuenta en redes cuyo estilo gráfico te guste y quieras tomar como inspiración?"},{"clave":"restricciones","etiqueta":"Restricciones","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"¿Hay algún caso en el que se pueda flexibilizar la aplicación de la marca? (Días festivos, eventos, promociones especiales, etc.)"},{"clave":"contenidoPrevio","etiqueta":"¿Qué tipo de contenido visual se ha usado en la marca hasta ahora?","tipo":"TEXTO_LARGO","obligatorio":false,"ayuda":"Fotos, videos, ilustraciones, etc."},{"clave":"consistencia","etiqueta":"¿Qué es lo que más te preocupa de la consistencia de la marca?","tipo":"TEXTO_LARGO","obligatorio":false},{"clave":"datoImportante","etiqueta":"¿Algún dato importante que debamos saber?","tipo":"TEXTO_LARGO","obligatorio":false}]')
ON CONFLICT (codigo) DO UPDATE SET nombre = excluded.nombre, descripcion = excluded.descripcion, servicios = excluded.servicios,
  dias_habiles = excluded.dias_habiles, campos = excluded.campos, activa = true;

UPDATE plantilla_proyecto pp SET requerimientos = x.requerimientos
FROM (VALUES
    ('SOCIAL_MEDIA_PRO', '', ARRAY['BRIEF_MARKETING','BRIEF_SOCIAL','ACCESOS_REDES','MANUAL_MARCA']::text[]),
    ('PAID_MEDIA', '', ARRAY['BRIEF_PERFORMANCE','ACCESOS_REDES']::text[]),
    ('BRANDFORMANCE', 'MARCA_NUEVA', ARRAY['BRIEF_BRANDING','BRIEF_NAMING']::text[])
  ) AS x(codigo, variante, requerimientos), servicio s
WHERE s.codigo = x.codigo AND pp.servicio_id = s.id AND coalesce(pp.variante, '') = x.variante AND pp.activa;

ALTER TABLE cliente ADD COLUMN ingreso jsonb;
COMMENT ON COLUMN cliente.ingreso IS 'Ingreso de cliente que llenó Comercial en el alta: {respuestas, registradoEn, registradoPorId}. Campos en src/dominio/briefs.ts (CAMPOS_INGRESO). Solo lo ve el equipo.';
